text=doc.read_text(encoding='utf-8-sig')
sha_in_doc=set(re.findall(r'(?<![0-9a-fA-F])[0-9a-fA-F]{64}(?![0-9a-fA-F])',text))
records=[];missing=[];uncited=[]
for group,items in entries.items():
 for label,rel in items:
  p=root/rel
  if not p.is_file(): missing.append({'group':group,'label':label,'path':rel}); continue
  h=hashlib.sha256(p.read_bytes()).hexdigest()
  r={'group':group,'label':label,'path':rel,'bytes':p.stat().st_size,'sha256':h,'sha256_cited_in_handover':h in sha_in_doc}
